#!/bin/sh
# Launcher for @APP_NAME@ — generated by the io.github.fiftieshousewife.java-app or .node-app plugin; do not edit.
#
# Usage: @APP_NAME@ run [args...] | healthcheck | version
#
# Environment (all optional):
#   APP_ROOT        install root; defaults to the directory above releases/ when installed
#                   with deploy/install.sh, else to the app directory itself
#   APP_CONF_DIR    default $APP_ROOT/conf
#   APP_DATA_DIR    default $APP_ROOT/data
#   APP_LOG_DIR     default $APP_ROOT/logs
#   APP_LOG_TARGET  file (default) or stdout
#   APP_PORT        port the application listens on, if any
#   APP_JAVA_OPTS / APP_NODE_OPTS  extra runtime options (word-split)
set -eu

# Resolve the real app directory, following symlinks to this script (POSIX, no readlink -f).
self=$0
while [ -h "$self" ]; do
  link=$(readlink "$self")
  case "$link" in
    /*) self=$link ;;
    *) self=$(dirname "$self")/$link ;;
  esac
done
APP_HOME=$(cd -P "$(dirname "$self")/.." && pwd -P)
APP_NAME='@APP_NAME@'

if [ -z "${APP_ROOT:-}" ]; then
  parent=$(dirname "$APP_HOME")
  if [ "$(basename "$parent")" = "releases" ]; then
    APP_ROOT=$(dirname "$parent")
  else
    APP_ROOT=$APP_HOME
  fi
fi
: "${APP_CONF_DIR:=$APP_ROOT/conf}"
: "${APP_DATA_DIR:=$APP_ROOT/data}"
: "${APP_LOG_DIR:=$APP_ROOT/logs}"
: "${APP_LOG_TARGET:=file}"
export APP_HOME APP_NAME APP_ROOT APP_CONF_DIR APP_DATA_DIR APP_LOG_DIR APP_LOG_TARGET

usage() {
  echo "Usage: $APP_NAME run [args...] | healthcheck | version" >&2
}

command=${1:-}
[ $# -gt 0 ] && shift
case "$command" in
  run) ;;
  healthcheck) set -- --healthcheck "$@" ;;
  version) cat "$APP_HOME/META-INF/app.json"; exit 0 ;;
  -h|--help|help) usage; exit 0 ;;
  *) usage; exit 64 ;;
esac

@POLICY@@EXEC@
